head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gMajContCdIndex = 100;
scwin.isFileDelete = false;
scwin.vJobMode = "";
scwin.vBZ_PROCS_NO = "";
scwin.trsIdx = "";
// 세션정보를 얻기위한 함수사용
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.initCode();
        scwin.vJobMode = $c.frame.path("../").scwin.vJobMode;
        await scwin.initCtrl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        if (scwin.vJobMode === "M") {
            await scwin.update();
        } else {
            await scwin.save();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Read_OnFail
 * @description Read On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Read_OnFail = async function() {
    try {
        await $c.win.alert(trs_Read.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.trs_Read_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.isFileDelete) scwin.callElasticFileNoti();
        $c.frame.path("../").fn_list_sync();
        dts_REAL_INVSTG_DATA.setCellData(1, "BZ_PROCS_NO", scwin.vBZ_PROCS_NO);
        scwin.vJobMode = "M";
        btn_Delete.setDisabled(false);
        btn_Delete.setBackgroundImage("../img/btn_delete.gif");
        await scwin.listSync();
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
        await $c.win.alert(trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Update_OnSuccess
 * @description Update On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnSuccess = async function() {
    try {
        if (scwin.isFileDelete) scwin.callElasticFileNoti();
        $c.frame.path("../").fn_list_sync();
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.trs_Update_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Update_OnFail
 * @description Update On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
        await $c.win.alert(trs_Update.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.trs_Update_OnFail" });
    }
};

/**
 * @method
 * @name trs_Delete_OnSuccess
 * @description Delete On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnSuccess = async function() {
    try {
        scwin.callElasticFileNoti();
        $c.frame.path("../").fn_list_sync();
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.trs_Delete_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Delete_OnFail
 * @description Delete On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        await $c.win.alert(trs_Delete.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.trs_Delete_OnFail" });
    }
};

/**
 * @method
 * @name dts_REAL_INVSTG_DATA_OnLoadError
 * @description dts_REAL_INVSTG_DATA 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_REAL_INVSTG_DATA_OnLoadError = async function() {
    try {
        await $c.win.alert('dts_REAL_INVSTG_DATA.OnLoadError()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.dts_REAL_INVSTG_DATA_OnLoadError" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20509.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20509.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
        if (scwin.vJobMode === "I") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
            file_name.setValue(inf_find.getValue());
        }
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20509.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_lineadd_onclick = function() {
    try {
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            if (scwin.vJobMode === "I") {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
            } else {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                let seq = dts_fileList.getRowPosition();
                for (i = 0; i < dts_fileList.getRowCount(); i++) {
                    if (dts_fileList.getCellData(i, "ATTACH_SEQ") === seq) {
                        seq++;
                        i = 0;
                    }
                }
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", seq);
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "BZ_PROCS_NO", scwin.vBZ_PROCS_NO);
                file_name.setValue(inf_find.getValue());
            }
        } else {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20509.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_linedelete_onclick = async function() {
    try {
        if (dts_fileList.getCellData(dts_fileList.getRowPosition(), "USR_TP_CD") === "3") await $c.win.alert("상장법인이 제출한 첨부파일은 삭제되지 않습니다.");

        else dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20509.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name grd_fileList_OnDblClick
 * @description grd_fileList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_OnDblClick = function(row, colid) {
    try {
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0 && dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename") !== "" && dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ") !== "") {
            $c.elw.fn_filedown();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20509.grd_fileList_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name initCode
 * @description init Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initCode = async function() {
    const arrCid = [{
        cid: "REAL_INVSTG_STEP_CD",
        cnm: "cmb_REAL_INVSTG_STEP_CD"
    }];
    let objCod;
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='REAL_INVSTG_STEP_CD'";
    const sbmOptions = {
        id : "sbm_dts_Code",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Code=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    let strGubun = "";
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Code.getRowCount(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strGubun = dts_Code.getCellData(j, "VALUE").substring(0, 1); // 코 1XX, 유 2XX
                if (scwin.gLdMktTp === strGubun) {
                    strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
                } else if (scwin.gLdMktTp === '9') {
                    strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
                }
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name chkChrg
 * @description chk Chrg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkChrg = async function() {
    if (js_usr_tp_cd === '1') {
        // 운영자이면
        return true;
    }
    const sbmOptions = {
        id : "sbm_dts_Chrg",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Chrg=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const chrgYn = dts_Chrg.getCellData(1, "CHRG_YN");
    if (chrgYn !== 'Y') {
        await $c.win.alert("해당종목 담당자와 담당 팀장만 변경 가능합니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/RealInvstg.do",
        ref : "dts_REAL_INVSTG_DATA,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.chkForm() === false) return;
    if (await scwin.chkChrg() === false) return;
    if (dts_fileList.getCellData(1, "fileInfo") === "") {
        dts_fileList.Reset();
    }
    let rtn = confirm('저장 하시겠습니까?');
    if (rtn === 1) {
        scwin.trsIdx = TRS_IDX_INSERT;
        scwin.preBuild();
        scwin.vBZ_PROCS_NO = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        dts_REAL_INVSTG_DATA1.setCellData(1, "BZ_PROCS_NO", scwin.vBZ_PROCS_NO);
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : scwin.trsIdx,
        //     COUNT : "0",
        //     BZ_PROCS_NO : scwin.vBZ_PROCS_NO,
        //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_207,
        //     LD_MKT_TP_CD : scwin.gLdMktTp,
        //     ISUR_CD : $c.stf.getObjectValue(txb_ISUR_CD)
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/RealInvstg.do",
            ref : "dts_REAL_INVSTG_DATA1,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.chkForm() === false) return;
    if (await scwin.chkChrg() === false) return;
    let rtn = confirm('수정 하시겠습니까?');
    if (rtn === 1) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        scwin.preBuild();
        // [전환검토] trs_Update.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : scwin.trsIdx,
        //     COUNT : "0",
        //     BZ_PROCS_NO : scwin.vBZ_PROCS_NO,
        //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_207,
        //     LD_MKT_TP_CD : scwin.gLdMktTp,
        //     ISUR_CD : $c.stf.getObjectValue(txb_ISUR_CD)
        // };
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/RealInvstg.do",
            ref : "dts_REAL_INVSTG_DATA1,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (await scwin.chkChrg() === false) return;
    let rtn = confirm('삭제 하시겠습니까?');
    if (rtn === 1) {
        scwin.trsIdx = TRS_IDX_DELETE;
        scwin.preBuild();
        ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_207 + ",LD_MKT_TP_CD=" + scwin.gLdMktTp + ",ISUR_CD=" + txb_ISUR_CD.getValue();
        // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : scwin.trsIdx,
        //     COUNT : "0",
        //     BZ_PROCS_NO : scwin.vBZ_PROCS_NO
        // };
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/RealInvstg.do",
            ref : "dts_REAL_INVSTG_DATA1",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name setFileDataHeader
 * @description set File Data Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setFileDataHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_fileList",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_fileList=body.content",
