    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setSaveHeader
 * @description set Save Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSaveHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_REAL_INVSTG_DATA",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_REAL_INVSTG_DATA=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_REAL_INVSTG_DATA.insertRow();
    dts_REAL_INVSTG_DATA.setCellData(dts_REAL_INVSTG_DATA.getRowPosition(), "REAL_INVSTG_MAJ_CONTN_CD1", "0");
    dts_REAL_INVSTG_DATA.setCellData(dts_REAL_INVSTG_DATA.getRowPosition(), "REAL_INVSTG_MAJ_CONTN_CD2", "0");
    dts_REAL_INVSTG_DATA.setCellData(dts_REAL_INVSTG_DATA.getRowPosition(), "REAL_INVSTG_MAJ_CONTN_CD3", "0");
    dts_REAL_INVSTG_DATA.setCellData(dts_REAL_INVSTG_DATA.getRowPosition(), "REAL_INVSTG_MAJ_CONTN_CD4", "0");
};

/**
 * @method
 * @name setButton
 * @description set Button 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setButton = async function() {
    const sbmOptions = {
        id : "sbm_param_Dts",
        action : "/listingCommon.do",
        ref : "",
        target : "param_Dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
