///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initCtrl
 * @description init Ctrl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initCtrl = async function() {
    if (scwin.gLdMktTp === "1") {
        lbl_stat_23.hide();
        lbl_stat_13.show("");
        scwin.gMajContCdIndex = 100; // 유가  1XX

    } else {
        lbl_stat_23.show("");
        lbl_stat_13.hide();
        scwin.gMajContCdIndex = 200; // 코스닥 2XX

    }
    if (scwin.vJobMode === 'M') {
        getBZ_PROCS_NO = $c.frame.path("../").fn_getBZ_PROCS_NO;
        scwin.vBZ_PROCS_NO = getBZ_PROCS_NO();
        btn_Delete.setDisabled(false);
        btn_Delete.setBackgroundImage("../img/btn_delete.gif");
        img_com_srch.hide();
        await scwin.listSync();
    } else {
        await scwin.setFileDataHeader();
        await scwin.setSaveHeader();
        btn_Delete.setDisabled(true);
        btn_Delete.setBackgroundImage("../img/btn_delete_d.gif");
    }
};

/**
 * @method
 * @name chkForm
 * @description chk Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkForm = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("'회사코드(명)'을 입력하세요.");
        return false;
    }
    if (txb_TITLE.getValue() === "") {
        await $c.win.alert("'제목'을 입력하세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name preBuild
 * @description pre Build 처리
 * @returns {void}
 * @hidden N
 */
scwin.preBuild = function() {
    $c.stf.copyDataSet(dts_REAL_INVSTG_DATA, dts_REAL_INVSTG_DATA1);
    dts_REAL_INVSTG_DATA1.setBroadcast(false);
    for (let i = 1; i <= 4; i++) {
        if (dts_REAL_INVSTG_DATA.getCellData(1, "REAL_INVSTG_MAJ_CONTN_CD" + i) === "1") {
            if (i === 4) dts_REAL_INVSTG_DATA1.setCellData(1, "REAL_INVSTG_MAJ_CONTN_CD" + i, scwin.gMajContCdIndex + 99);

            else dts_REAL_INVSTG_DATA1.setCellData(1, "REAL_INVSTG_MAJ_CONTN_CD" + i, scwin.gMajContCdIndex + i);
        } else dts_REAL_INVSTG_DATA1.setCellData(1, "REAL_INVSTG_MAJ_CONTN_CD" + i, "");
    }
    dts_REAL_INVSTG_DATA1.setBroadcast(true, true);
    if ($c.cp.isModified(dts_fileList)) {
        scwin.isFileDelete = true;
    }
};

/**
 * @method
 * @name filedown
 * @description filedown 처리
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function() {
    location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF20509.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + dts_fileList.getCellData(dts_fileList.getRowPosition(), "BZ_PROCS_NO") + "&SEQ=" + dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ") + "&gubun=48";
};

/**
 * @method
 * @name callElasticFileNoti
 * @description call Elastic File Noti 처리
 * @returns {void}
 * @hidden N
 */
scwin.callElasticFileNoti = function() {
    $.ajax({
        type: "POST",
        url: "/elasticNoti.do",
        data: {
            method: "notiElasticCommon",
            P_bzProcsNo: scwin.vBZ_PROCS_NO,
            url: "/index/tbld_real_invstg_data_file/kafka",
            type: "POST"
        },
        async: true
    });
    scwin.isFileDelete = false;
};

